prompt --application/shared_components/user_interface/lovs/available_schemas
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(32831138667365511)
,p_lov_name=>'AVAILABLE SCHEMAS'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select u.username',
'  from all_users u',
' where u.oracle_maintained = ''N''',
'   and u.username <> sys_context(''USERENV'', ''CURRENT_SCHEMA'')',
'   and exists (select 1 from all_tables t where t.owner = u.username)'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_query_owner=>'FTSTG'
,p_return_column_name=>'USERNAME'
,p_display_column_name=>'USERNAME'
,p_default_sort_column_name=>'USERNAME'
,p_default_sort_direction=>'ASC'
);
end;
/
