,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.owner as table_owner, t.table_name, q.queue_name, t.num_rows, nvl(s.total_sent, 0) as total_sent',
'  from all_tables t',
'  join oqf_tables o',
'    on o.owner = t.owner',
'   and o.table_name = t.table_name',
'  join oqf_eventhub_queues q',
'    on o.queue = q.id',
' cross apply (select sum(num_rows) as total_sent',
'                from oqf_logs l',
'               where text = ''201''',
'                 and l.owner = o.owner',
'                 and l.table_name = o.table_name) s',
' where t.owner ||''.''|| t.table_name in (select fullname from env_table_list(p_environment => :ENVIRONMENT))',
' order by t.owner, t.table_name'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(25745717562447347)
