wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(26404110769419019)
,p_computation_sequence=>10
,p_computation_item=>'P7_ROWKEY'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_rowkey varchar2(128);',
'begin',
'  select listagg(cols.column_name, ''||'') within group(order by position)',
'    into l_rowkey',
'    from all_cons_columns cols',
'    join all_constraints cons',
'      on cons.constraint_name = cols.constraint_name',
'     and cons.owner = cols.owner',
'     and cons.table_name = cols.table_name',
'   where cols.owner = :P5_TABLE_OWNER',
'     and cols.table_name = :P5_TABLE_NAME',
'     and cons.constraint_type = ''P''',
'   order by cols.table_name, cols.position;',
'',
'  if l_rowkey is null then',
'    select c.column_name',
'      into l_rowkey',
'      from all_tab_columns c',
'     where c.owner = :P5_TABLE_OWNER',
'       and c.table_name = :P5_TABLE_NAME',
'       and c.column_id = 1;',
'  end if;',
'  return l_rowkey;',
'exception',
'  when no_data_found then',
'    select ''ORA_HASH('' || listagg(c.column_name, ''||'') within group(order by c.column_id) || '')''',
'      into l_rowkey',
'      from all_tab_columns c',
'     where c.owner = :P5_TABLE_OWNER',
'       and c.table_name = :P5_TABLE_NAME',
'       and c.data_type != ''DATE''',
'       and c.column_id <= 5;',
'  ',
'    return l_rowkey;',
'end;',
''))
,p_compute_when=>'P7_ROWKEY'
,p_compute_when_type=>'ITEM_IS_NULL'
);
end;
