wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(28417128060624142)
,p_plug_name=>'Synchronization Summary'
,p_region_name=>'summaryReport'
,p_icon_css_classes=>'fa-table-bookmark'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(25700352355447336)
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select l.transaction_id,',
'       l.owner,',
'       l.table_name,',
'       l.text,',
'       min(l.created) as started,',
'       max(l.created) as last_batch,',
'       sum(l.num_rows) as total_records,',
'       round(avg(l.num_rows), 2) as average_batch,',
'       sum(l.bytes) as sum_bytes,',
'       round(avg(l.bytes), 2) as average_size,',
'       sum(l.send_time) as sum_sync_time,',
'       round(avg(l.send_time), 2) as average_time,',
'       count(*) as batches_count',
'  from oqf_logs l',
' where l.created >= trunc(sysdate, ''dd'') - :P10_PERIOD',
'   and transaction_id is not null',
'   and l.owner || ''.'' || l.table_name in (select fullname from env_table_list(p_environment => :ENVIRONMENT))',
' group by l.transaction_id, l.owner, l.table_name, l.text',
' order by max(created) desc'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P10_PERIOD'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Synchronization Summary'
