wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(27045673573538049)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process Columns'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_oldarr  apex_t_varchar2;',
'  l_newarr  apex_t_varchar2;',
'  l_upd_col oqf_table_columns.column_name%type;',
'begin',
'  l_newarr := apex_string.split(p_str => :P12_COLUMNS, p_sep => '':'');',
'',
'  select ac.column_id',
'    bulk collect',
'    into l_oldarr',
'    from oqf_table_columns oc',
'    join all_tab_columns ac',
'      on oc.owner = ac.owner',
'     and oc.table_name = ac.table_name',
'     and oc.column_name = ac.column_name',
'   where oc.owner = :P12_OWNER',
'     and oc.table_name = :P12_TABLE_NAME',
'   order by oc.column_order;',
'',
'  if l_newarr <> l_oldarr /* New column list */',
'     or apex_string.join(p_table => l_newarr, p_sep => '':'') <> :P12_COLUMNS /*New column order */',
'   then',
'  ',
'    delete from oqf_table_columns oc',
'     where oc.owner = :P12_OWNER',
'       and oc.table_name = :P12_TABLE_NAME;',
'  ',
'    insert into oqf_table_columns',
'      (owner, table_name, column_name, column_order)',
'      select ac.owner, ac.table_name, ac.column_name, rownum',
'        from all_tab_columns ac',
'        join table(l_newarr) t',
'          on ac.column_id = t.column_value',
'       where ac.owner = :P12_OWNER',
'         and ac.table_name = :P12_TABLE_NAME;',
'  ',
'    commit;',
'  ',
'  end if;',
'',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(27436078052489112)
,p_process_success_message=>'Table Updated!'
,p_internal_uid=>27045673573538049
);
