,p_plug_display_sequence=>40
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_jwt     apex_jwt.t_token;',
'  l_payload json_object_t;',
'  l_keys    json_key_list;',
'  l_resp    clob;',
'begin',
'  l_jwt := apex_jwt.decode(p_value => :TOKEN);',
'  l_payload := json_object_t.parse(l_jwt.payload);',
'  l_keys    := l_payload.get_keys();',
'',
'  for i in 1 .. l_keys.count loop',
'    l_resp := l_resp || l_keys(i) || '' = '' || l_payload.get_string(l_keys(i)) || ''<br>'';',
'  end loop;',
'',
'  return l_resp;',
'end;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
