 p_id=>wwv_flow_imp.id(32819550907201626)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(32818379438201614)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Schemas - Save Interactive Grid Data'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'  case :APEX$ROW_STATUS',
'    when ''C'' then',
'      insert into oqf_environment_schemas',
'        (environment, owner, all_tables, created, created_by)',
'      values',
'        (:P15_ENVIRONMENT, :OWNER, :ALL_TABLES, sysdate, :APP_USER)',
'      returning id into :ID;',
'    when ''U'' then',
'      update oqf_environment_schemas s',
'         set s.owner      = :OWNER,',
'             s.all_tables = :ALL_TABLES,',
'             s.updated    = sysdate,',
'             s.updated_by = :APP_USER',
'       where id = :ID;',
'    when ''D'' then',
'      delete oqf_environment_schemas where id = :ID;',
'  end case;',
'end;',
''))
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>32819550907201626
);
